    static PointerCalibration Kyles()
    {
        using var doc = JsonDocument.Parse(Json);
        var r = doc.RootElement;
        var depths = r.GetProperty("Depths").EnumerateArray().Select(e => e.GetDouble()).ToList();
        var aims = r.GetProperty("Aims").EnumerateArray().Select(a => new Vec2(a[0].GetDouble(), a[1].GetDouble())).ToList();
        var seen = r.GetProperty("Seen").EnumerateArray()
            .Select(row => (IReadOnlyList<Vec2?>)[.. row.EnumerateArray().Select(p => p.ValueKind == JsonValueKind.Array ? new Vec2(p[0].GetDouble(), p[1].GetDouble()) : (Vec2?)null)]).ToList();
        return new PointerCalibration(depths, aims, seen);
    }

    [Fact]
    public void GlintsAreLeftOutOfTheCalibration()
    {
        var cal = Kyles();
        // X 85–123 on the Y 100 row: all the glint (about 3590, 800 px at every one).
        for (int i = 0; i < 5; i++) Assert.All(cal.Good[i], p => Assert.Null(p));
        // A real spot: X 151.5, Y 100 moves along its track; its one glint (at +6 mm) is left out.
        Assert.NotNull(cal.Good[7][0]);
        Assert.Null(cal.Good[7][7]);
        // X 113.5, Y 110 saw the real spot three times (about 1937 px across): those stay.
        Assert.NotNull(cal.Good[14][1]);
        Assert.NotNull(cal.Good[14][3]);
        Assert.NotNull(cal.Good[14][7]);
        Assert.Null(cal.Good[14][0]);
    }

    [Fact]
    public void KylesClearPhotosReadTheBarsTop()
    {
        // His scan's second stop (head focused at 78.5 mm; the machine's auto-focus said the top was at 74.5 in the middle).
        var cal = Kyles();
        double? At(double x, double px, double py) => cal.Depth(new Vec2(x, 110), new Vec2(px, py)) is { } d ? 78.5 - d : null;
        Assert.InRange(At(169.5, 589, 2313)!.Value, 73.5, 75.5);
        Assert.InRange(At(142.8, 1236, 1952)!.Value, 73, 76);
        Assert.InRange(At(116, 1880, 1602)!.Value, 73, 76);
        // The glint is never read as the part.
        Assert.Null(cal.Depth(new Vec2(89.3, 110), new Vec2(3582, 516)));
    }
